{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": [
      {
        "ref": "L01",
        "text": "(不及安石雖居藩/中興書曰萬噐量)"
      },
      {
        "ref": "L02",
        "text": "(名稱居萬上也/任安在私門之時)"
      }
    ]
  },
  "frozen_questions": [
    {
      "gap": "这段行动或处境为何影响正文理解？",
      "question_id": "Q1",
      "story_span": "王右軍問許玄度卿自言何如安石許未荅王"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": [
      {
        "layer": "collation_note",
        "ref": "J01",
        "source_labels": [],
        "speaker": null,
        "text": "「何如安石」「石」，沈本作「萬」。「相為雄」「為」，景宋本作「與」。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J02",
        "source_labels": [],
        "speaker": "程炎震",
        "text": "〔一〕 程炎震云：「宋本石作萬。」"
      }
    ]
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "王右軍問許玄度卿自言何如安石許未荅王因曰\n安石故相爲雄阿萬當裂眼争邪"
  },
  "story_id": "09-pinzao-055"
}
